  ('conferences','seminar','/ˈsemɪnɑːr/','noun','hội thảo chuyên đề','The seminar introduces new methods for managing inventory.','Hội thảo giới thiệu phương pháp mới để quản lý hàng tồn kho.'),
  ('conferences','workshop','/ˈwɜːrkʃɑːp/','noun','buổi thực hành','Participants will practice negotiation skills in the workshop.','Người tham dự sẽ thực hành kỹ năng đàm phán trong buổi học.'),
  ('conferences','capacity','/kəˈpæsəti/','noun','sức chứa','The room has a capacity of two hundred people.','Phòng có sức chứa hai trăm người.'),
  ('conferences','acoustics','/əˈkuːstɪks/','noun','hệ thống âm học','The venue’s acoustics are suitable for large presentations.','Hệ thống âm học của địa điểm phù hợp với các bài thuyết trình lớn.'),
  ('conferences','equipment','/ɪˈkwɪpmənt/','noun','thiết bị','Technicians tested the audio equipment before the event.','Kỹ thuật viên kiểm tra thiết bị âm thanh trước sự kiện.'),
  ('conferences','catering','/ˈkeɪtərɪŋ/','noun','dịch vụ ăn uống','The catering team will serve lunch in the lobby.','Đội phục vụ sẽ dọn bữa trưa tại sảnh.'),
  ('conferences','sponsor','/ˈspɑːnsər/','noun','nhà tài trợ','The main sponsor will have a display near the entrance.','Nhà tài trợ chính sẽ có gian trưng bày gần lối vào.'),
  ('conferences','itinerary','/aɪˈtɪnəreri/','noun','lịch trình chuyến đi','The assistant sent the speaker’s travel itinerary.','Trợ lý đã gửi lịch trình chuyến đi của diễn giả.'),
  ('conferences','invitation','/ˌɪnvɪˈteɪʃn/','noun','lời mời','The department sent invitations to its business partners.','Phòng ban đã gửi lời mời tới các đối tác kinh doanh.')
),
numbered AS (
  SELECT t.id AS topic_id, s.word, s.phonetic, s.part_of_speech, s.meaning_vi,
         s.example_en, s.example_vi,
         row_number() OVER (PARTITION BY t.id ORDER BY s.word)::smallint AS display_order
  FROM seed s
  JOIN app.vocab_topics t ON t.slug = s.topic_slug
)
INSERT INTO app.vocab_words
  (topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, display_order)
SELECT topic_id, word, phonetic, part_of_speech, meaning_vi, example_en, example_vi, display_order
FROM numbered
ON CONFLICT (topic_id, word) DO UPDATE SET
  phonetic = EXCLUDED.phonetic,
  part_of_speech = EXCLUDED.part_of_speech,
  meaning_vi = EXCLUDED.meaning_vi,
  example_en = EXCLUDED.example_en,
  example_vi = EXCLUDED.example_vi,
  display_order = EXCLUDED.display_order;
